chartjs.data:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	cal = d -> $d.toSystemCalendar();
	today = now().roundDay();

	// The left edge of the axis. For "Alle" that is the oldest run there is, found by
	// sorting the start dates - the one extra pass over the table that this option needs
	// and a bounded period does not.
	first = ifElse($period > 0,
		$cal($today).withDayAdded(-$period).toDate().roundDay(),
		ifElse(isEmpty($executions), $today,
			$executions.map(e -> $startedAt($e)).sort().firstElement().roundDay()));

	// One bar per day while a reader can still count the bars, one bar per month beyond
	// that. Only "Alle" can reach the second case, and it has to: a monitor that has been
	// collecting for a year would otherwise draw four hundred hairlines.
	monthly = ($today.toMillis() - $first.toMillis()) / 86400000 > 120;

	// The buckets, oldest first. The month count is exact calendar arithmetic rather than a
	// division of the day span: a span of a few weeks can straddle three months, and an
	// undershoot would drop a whole month of runs without a trace. The day count is a
	// millisecond division, deliberately generous by one and then trimmed against the left
	// edge, because that division comes out one short across a daylight-saving shift.
	depth = ifElse($monthly,
		($cal($today).year() - $cal($first).year()) * 12
			+ $cal($today).month() - $cal($first).month(),
		($today.toMillis() - $first.toMillis()) / 86400000 + 1);
	buckets = ifElse($monthly,
		$cal($today).withDay(1).toDate().roundDay()
			.recursion(d -> $cal($d).withMonthAdded(-1).toDate(), 0, $depth)
			.reverse(),
		$today.recursion(d -> $cal($d).withDayAdded(-1).toDate().roundDay(), 0, $depth)
			.reverse()
			.filter(b -> $b >= $first));
	bucketOf = d -> ifElse($monthly, $cal($d).withDay(1).toDate().roundDay(), $d.roundDay());

	byBucket = $executions
		.filter(e -> $startedAt($e) >= $buckets.firstElement())
		.groupBy(e -> $bucketOf($startedAt($e)));
	counts = status -> $buckets.map(b -> {
		runs = $byBucket[$b];
		ifElse(isEmpty($runs), 0,
			$runs.filter(e -> $e.get(`tl.ai.execution:AgentExecution#status`) == $status).size());
	});
	bar = status -> color -> {
		'label': $status.label(),
		'data': $counts($status),
		'backgroundColor': $color
	};
	{
		'type': 'bar',
		'data': {
			'labels': $buckets.map(b -> ifElse($monthly,
				dateFormat('MM.yyyy').format($b),
				dateFormat('dd.MM.').format($b))),
			'datasets': list(
				$bar(`tl.ai.execution:ExecutionStatus#COMPLETE`)('#04a38d'),
				$bar(`tl.ai.execution:ExecutionStatus#ERROR`)('#d3181b'),
				$bar(`tl.ai.execution:ExecutionStatus#REJECTED`)('#d3a118'),
				$bar(`tl.ai.execution:ExecutionStatus#CANCELLED`)('#8a8a8a'),
				$bar(`tl.ai.execution:ExecutionStatus#RUNNING`)('#2968c8')
			)
		},
		'options': {
			'maintainAspectRatio': false,
			'plugins': { 'legend': { 'position': 'bottom' } },
			'scales': {
				'x': { 'stacked': true },
				'y': { 'stacked': true, 'beginAtZero': true }
			}
		}
	};
}
